select md5(string_agg(tablename || ':' || (xpath('/row/c/text()', query_to_xml(format('select count(*) as c from public.%I', tablename), false, true, '')))[1]::text, ',' order by tablename)) as fingerprint, count(*) as tables, sum(((xpath('/row/c/text()', query_to_xml(format('select count(*) as c from public.%I', tablename), false, true, '')))[1]::text)::bigint) as total_rows from pg_tables where schemaname = 'public';
